    }
    if (phase === "pausing") {
      patch.pausedAt = now;
      patch.acks = {};
      patch.mergedAt = null;
      patch.syncedAt = null;
    }
    if (phase === "merging") patch.mergedAt = now;
    if (phase === "syncing") patch.syncedAt = now;
    if (phase === "idle") {
      patch.blessedJobId = null;
