                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Perimeter scoreboard ??? Top-1 vs Top-3"
            subtitle="Cross-lens scatter; bubble size tracks Top-3"
          >
            <div className="h-80 w-full min-w-0">
