                    name="Top-3"
                    unit="%"
                    domain={[20, 100]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Top-3 %",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[80, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      typeof v === "number" ? fmtPct(Number(v), 0) : v,
                      name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                  />
                  <Scatter data={lensScatter}>
                    {lensScatter.map((l) => (
                      <Cell key={l.id} fill={l.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Cumulative share vs equal split"
            subtitle="Lorenz-style concentration curves by perimeter"
          >
            <div className="mb-3 flex flex-wrap gap-3">
              <ToggleGroup
                label="Curve"
                value={curveLens}
                onChange={setCurveLens}
                options={[
                  { id: "growth", label: "Growth" },
                  { id: "growth-q2", label: "Growth Q2" },
                  { id: "ppp", label: "PPP stock" },
                  { id: "trade", label: "Trade" },
                  { id: "exports", label: "Exports" },
                ]}
              />
              <ToggleGroup
                label="Equal split"
                value={showEqualLine ? "on" : "off"}
                onChange={(v) => setShowEqualLine(v === "on")}
                options={[
                  { id: "on", label: "Show" },
                  { id: "off", label: "Hide" },
                ]}
              />
            </div>
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={curve}
