              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={hardDumbbells}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="label"
                    width={120}
                    tick={{ fontSize: 10 }}
                  />
                  <Tooltip
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "julyPath" ? "July path" : "Hard signal",
                    ]}
                  />
                  <Bar
                    dataKey="julyPath"
                    name="julyPath"
                    fill="#cbd5e1"
                    radius={[0, 4, 4, 0]}
                  />
                  <Bar
                    dataKey="hardSignal"
                    name="hardSignal"
                    radius={[0, 4, 4, 0]}
                  >
                    {hardDumbbells.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "prices" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="CPI vs growth ??? price dispersion"
            subtitle="Bubble size = PPP stock share; China leads growth with near-zero CPI"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="CPI"
                    unit="%"
                    domain={[0, 5.5]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "CPI YoY %",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="GDP"
                    unit="%"
                    domain={[0, 8.5]}
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "GDP %",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      `${Number(v).toFixed(1)}%`,
                      name === "x" ? "CPI" : name === "y" ? "GDP" : name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.label ?? ""
                    }
                  />
                  <Scatter data={priceScatter}>
                    {priceScatter.map((p) => (
                      <Cell key={p.id} fill={p.fill} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title={
              pricePanel === "cooling"
                ? "August price-cooling path"
                : "YoY vs SAAR / IMF dual meter"
            }
            subtitle={
              pricePanel === "cooling"
                ? "Prior month ??? latest YoY; US cools, EA edges hotter"
                : "Unit mismatch is the story ??? not a share rewrite"
            }
          >
            <div className="mb-3">
              <ToggleGroup
                label="Price panel"
                value={pricePanel}
                onChange={setPricePanel}
                options={[
                  { id: "cooling", label: "Cooling path" },
                  { id: "dual", label: "YoY vs SAAR" },
                ]}
              />
            </div>
            {pricePanel === "cooling" ? (
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={PRICE_COOLING_PATH}
                    margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="label" tick={{ fontSize: 10 }} />
                    <YAxis tick={{ fontSize: 11 }} unit="%" />
                    <Tooltip
                      formatter={(v, name) => [
                        `${Number(v).toFixed(1)}%`,
                        name === "priorYoy" ? "Prior" : "Latest",
                      ]}
                    />
                    <Bar dataKey="priorYoy" name="priorYoy" fill="#cbd5e1" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="latestYoy" name="latestYoy" radius={[4, 4, 0, 0]}>
                      {PRICE_COOLING_PATH.map((d) => (
                        <Cell key={d.id} fill={d.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            ) : (
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={DUAL_INFLATION}
                    margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="label" tick={{ fontSize: 9 }} interval={0} />
                    <YAxis tick={{ fontSize: 11 }} unit="%" />
                    <Tooltip
                      formatter={(v, name) => [
                        `${Number(v).toFixed(1)}%`,
                        name === "yoy" ? "YoY" : "SAAR / IMF",
                      ]}
                    />
                    <Bar dataKey="yoy" name="yoy" fill="#94a3b8" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="saarOrImf" name="saarOrImf" radius={[4, 4, 0, 0]}>
                      {DUAL_INFLATION.map((d) => (
                        <Cell key={d.id} fill={d.fill} />
                      ))}
                    </Bar>
                    <Line
                      type="monotone"
                      dataKey="spreadPp"
                      stroke="#f59e0b"
                      strokeWidth={2}
                      dot={{ r: 4 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            )}
            <p className="mt-3 text-sm leading-relaxed text-slate-600">
              Elevated-CPI economies still account for roughly{" "}
              {fmtPct(HEADLINE.elevatedCpiGdpSharePct)} of world PPP GDP. China (
              {fmtPct(HEADLINE.chinaCpi2025, 1)} CPI) leads growth contribution
              while contributing almost nothing to the global price impulse.
            </p>
          </ChartCard>
        </div>
      )}

      {view === "growth" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title={
              growthVintage === "q2"
                ? "Q2 sensitivity ??? world PPP growth contribution"
                : "World PPP growth contribution ladder"
            }
            subtitle={
              growthVintage === "q2"
                ? "Illustrative run-rate using China 4.3% YoY and US 1.5% SAAR"
                : "Carried 2025 weight ?? growth / world growth"
            }
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={growthBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 35]}
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={40}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      fmtPct(Number(v), 1),
                      "Share of world growth",
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.label ?? ""}
                  />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {growthBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="PPP GDP stock ladder"
            subtitle="Carried ~2025 weights ??? China ?? US ?? India = 42% Top-3"
          >
            <div className="h-96 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={pppBars}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 22]}
                    tick={{ fontSize: 11 }}
                    unit="%"
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={40}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v) => [
                      fmtPct(Number(v), 1),
                      "PPP stock share",
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.label ?? ""}
                  />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {pppBars.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "trade" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Merchandise trade-growth contribution"
            subtitle="WTO 2025 regional decomposition ??? Asia 71% / 3.2 pp"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={tradePie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {tradePie.map((s) => (
                      <Cell key={s.name} fill={s.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v) => [
                      fmtPct(Number(v), 0),
                      "Share of vol. growth",
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="CPB merchandise volume ??? May held, June pending"
            subtitle="Mar???May MoM path; June due 25 Aug is a flow overlay, not a share re-rank"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart
                  data={cpbChart}
                  margin={{ top: 12, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="month" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" domain={[-3, 2]} />
                  <Tooltip
                    formatter={(v, _n, item) => {
                      const pending = item?.payload?.isPending;
                      if (pending) return ["pending 25 Aug", "CPB June"];
                      return [`${Number(v).toFixed(1)}% MoM`, "CPB"];
                    }}
                  />
                  <Line
                    type="monotone"
                    dataKey="momPlot"
                    stroke="#0ea5e9"
                    strokeWidth={3}
                    connectNulls={false}
                    dot={{ r: 5, fill: "#0ea5e9" }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Goods export value shares"
            subtitle="China ?? US ?? Germany = 29% Top-3 of ~$26.3T merch exports"
          >
            <div className="h-80 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={exportNamed}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                  <YAxis tick={{ fontSize: 11 }} unit="%" />
                  <Tooltip
                    formatter={(v) => [
                      fmtPct(Number(v), 1),
                      "Export value share",
                    ]}
                    labelFormatter={(_, p) => p?.[0]?.payload?.label ?? ""}
                  />
                  <Bar dataKey="sharePct" radius={[4, 4, 0, 0]}>
                    {exportNamed.map((r) => (
                      <Cell key={r.id} fill={r.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Pending flow meters"
            subtitle="What Aug cannot yet restate on the concentration scoreboard"
          >
            <ul className="space-y-4 text-sm text-slate-600">
              {PENDING_METERS.map((m) => (
                <li
                  key={m.id}
                  className="rounded-lg border border-dashed border-slate-200 bg-slate-50 px-4 py-3"
                >
                  <div className="flex items-center justify-between gap-2">
                    <p className="font-semibold text-slate-800">{m.label}</p>
                    <span
                      className="rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-white"
                      style={{ background: m.fill }}
                    >
                      {m.dueDate}
                    </span>
                  </div>
                  <p className="mt-1 text-xs text-slate-500">
                    Held: {m.heldSignal} ??? {m.note}
                  </p>
                </li>
              ))}
              {SCOREBOARD.map((s) => (
                <li
                  key={s.id}
                  className="flex gap-3 border-b border-slate-100 pb-2"
                >
                  <span
                    className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full"
                    style={{ background: s.color }}
                  />
                  <div>
                    <p className="font-semibold text-slate-800">
                      {s.label}: Top-1 {fmtPct(s.top1Pct)} ?? Top-3{" "}
                      {fmtPct(s.top3Pct)}
                    </p>
                    <p className="text-xs text-slate-500">
                      {s.confidence} ??? {s.note}
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

